void zhengshoutiaoSummaryScreenViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &buttonBack)
    {
        //backInteraction
        //When buttonBack clicked change screen to ChooseActionScreen
        //Go to ChooseActionScreen with block transition
        application().gotoChooseActionScreenScreenBlockTransition();
    }
    if (&src == &btnRetry)
    {
        //retryInteraction
        //When btnRetry clicked call virtual function
        //Call onRetryClicked
        onRetryClicked();
        //retryChangeInteraction
        //When btnRetry clicked change screen to zhengshoutiaoTestScreen
        //Go to zhengshoutiaoTestScreen with block transition
        application().gotozhengshoutiaoTestScreenScreenBlockTransition();
    }
    if (&src == &btnDetail)
    {
        //detailInteraction
        //When btnDetail clicked call virtual function
        //Call onDetailClicked
        onDetailClicked();
        //detailChangeInteraction
        //When btnDetail clicked change screen to zhengshoutiaoDetailScreen
        //Go to zhengshoutiaoDetailScreen with screen transition towards East
        application().gotozhengshoutiaoDetailScreenScreenWipeTransitionEast();
    }
}
